function test_roundedAmountOutShiftsPriceBoundsCheck() public {
    // Setup: Token with tight max pricing bound
    uint160 maxPrice = 100000 * (2**96); // 100000:1 ratio
    vm.prank(address(registry));
    hook.registryUpdatePricingBounds(tokenIn, pairs, zeros, maxPrices);
    // Open order at exactly maxPrice with minimum order size
    uint256 minOrder = handler.getGroupKeyMinimumOrder(gk);
    // Calculate what validateHandlerOrder will see
    uint256 roundedOut = FullMath.mulDivRoundingUp(
        FullMath.mulDivRoundingUp(minOrder, maxPrice, Q96), maxPrice, Q96
    );
    // The exact output would be minOrder * maxPrice^2 / Q96^2
    uint256 exactOut = FullMath.mulDiv(
        FullMath.mulDiv(minOrder, maxPrice, Q96), maxPrice, Q96
    );
    // roundedOut > exactOut, so computeRatioX96 will return a higher price
    // This higher price may exceed maxPrice, causing false revert
    vm.prank(maker);
    vm.expectRevert(); // False positive revert
    handler.openOrder(tokenIn, tokenOut, maxPrice, minOrder, gk, maxPrice, hd);
}

