    // Close all P2 orders
    vm.prank(makerB);
    handler.closeOrder(tIn, tOut, P2, nB1, gk);
    vm.prank(makerC);
    handler.closeOrder(tIn, tOut, P2, nC1, gk);
    // P2 should be removed from linked list now
    // Re-add order at P2
    vm.prank(makerD);
